import { words, groupBy } from 'es-toolkit';
import { truncate } from 'es-toolkit/compat';

export interface Row {
  id: number;
  name: string;
  age: number;
}

export type Config = Record<string, unknown>;

export function tokens(text: string): string[] {
  return words(text);
}

export function byAge(rows: Row[]): Record<string, Row[]> {
  return groupBy(rows, (row) => row.age);
}

export function preview(text: string): string {
  return truncate(text, { length: 24 });
}
EOF
cat > $TEMP/t.mjs <<'EOF'
import {words as w1} from 'es-toolkit'; import {words as w2} from 'es-toolkit/compat';
const ch='abAB Zz09-_.'.split('');let bad=0;
for(let i=0;i<200000;i++){let s='';const n=Math.random()*40|0;for(let j=0;j<n;j++)s+=ch[Math.random()*ch.length|0];
if(JSON.stringify(w1(s))!==JSON.stringify(w2(s))){bad++;if(bad<5)console.log(JSON.stringify(s),w1(s),w2(s))}}
console.log('bad',bad)
EOF
cp $TEMP/t.mjs ./t.mjs && node t.mjs; rm t.mjs; npm run size -- out/module.ts; npx tsc --noEmit -p . 2>&1 | head

